typedef float rational_t;
class vector3d;

class Random {
public:
  unsigned int NextRand();
  float randf(float begin, float end) {
    unsigned int r = NextRand();
    return r * (1.0f/32767)*(end-begin) + begin;
  }
};
extern Random *g_random_ptr;
inline float random(float begin,float end) {
  float r = g_random_ptr->randf(begin, end);
  return r;
}
#define PLUS_MINUS_ONE (random(-1.0f, 1.0f))

class physical_interface {
  char base[8];
  unsigned int flags;
public:
  enum { _PHYS_GRAVITY = 0x00000004 };
  void set_flag(unsigned int flag, bool val = true) { if(val) flags |= flag; else flags &= ~flag; }
  void set_gravity(bool val = true) { set_flag(_PHYS_GRAVITY, val); }
};

class guidance_system {
protected:
  physical_interface *owner;
  int flags;
public:
  void launch(const vector3d &dir, rational_t force);
};

class rocket_guidance_sys : public guidance_system {
protected:
  char target_pos[12];
  void *target;
  rational_t launch_force;
  rational_t wobble_timer;
  rational_t guidance_delay;
  rational_t accel_delay;
  rational_t guided_accuracy;
  rational_t turn_factor;
  rational_t accel_factor;
  rational_t full_wobble_timer;
  rational_t full_guidance_delay;
  rational_t full_accel_delay;
  rational_t wobble_timer_var;
  rational_t guidance_delay_var;
  rational_t accel_delay_var;
public:
  rational_t get_guidance_delay_with_var() const { return(full_guidance_delay + (PLUS_MINUS_ONE*guidance_delay_var)); }
  rational_t get_accel_delay_with_var() const { return(full_accel_delay + (PLUS_MINUS_ONE*accel_delay_var)); }
  void launch(const vector3d &dir, rational_t force);
};

void rocket_guidance_sys::launch(const vector3d &dir, rational_t force)
{
  launch_force = force;

  guidance_delay = get_guidance_delay_with_var();
  accel_delay = get_accel_delay_with_var();
  wobble_timer = 0.0f;

  owner->set_gravity(false);

  guidance_system::launch(dir, force);
}
